$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Target = Join-Path $Root "scripts\entity\repair-cached-emet-failures.js"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Root ".private\entity\backups\P04-targeted-final-repair-v2-$Timestamp"

Write-Host "Installing P04 targeted final repair v2.0.0..." -ForegroundColor Cyan

if (-not (Test-Path (Join-Path $Root "scripts\entity\build-cached-emet-explanations.js"))) {
    throw "Run this installer from the EMETSEES project root."
}

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $Target -Parent) | Out-Null

if (Test-Path $Target) {
    Copy-Item $Target (Join-Path $BackupDir "repair-cached-emet-failures.js") -Force
}

$Payload = @'

'@

try {
    [System.IO.File]::WriteAllBytes($Target, [System.Convert]::FromBase64String(($Payload -replace '\s','')))

    & node --check $Target
    if ($LASTEXITCODE -ne 0) { throw "The repair v2 script failed JavaScript syntax validation." }

    & node $Target --self-test
    if ($LASTEXITCODE -ne 0) { throw "The repair v2 self-test failed." }

    Write-Host "" 
    Write-Host "Inspecting the first 10 current failures without making an API request..." -ForegroundColor Cyan
    & npm run repair:cached-emet -- --plan --limit 10
    if ($LASTEXITCODE -ne 0) { throw "The repair v2 plan failed." }

    Write-Host ""
    Write-Host "P04 targeted final repair v2.0.0 installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupDir"
    Write-Host ""
    Write-Host "Next command:"
    Write-Host "npm run repair:cached-emet -- --limit 10 --concurrency 2 --attempts 2" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "This preserves all accepted caches and repairs only current failures."
}
catch {
    Write-Warning "Installation failed. Restoring the previous repair script..."
    $Backup = Join-Path $BackupDir "repair-cached-emet-failures.js"
    if (Test-Path $Backup) {
        Copy-Item $Backup $Target -Force
    } elseif (Test-Path $Target) {
        Remove-Item $Target -Force
    }
    throw
}
